package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.BusinessSessionProtocol;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
public class ConnectionCompletedProofTest extends ConnectionCompletedProofFixture {
 public ConnectionCompletedProofTest()throws Exception{}
 @Test void actualSdkBytesMintRealPrivateSettledProof()throws Exception{var p=proof();assertEquals(invocation,p.invocationId());assertEquals(verification,p.verificationId());assertEquals(new BigDecimal("0.00000500"),p.settledAmount());assertEquals(sent.toInstant(ZoneOffset.UTC),p.verifiedAt());assertEquals(sent.plusMinutes(1).toInstant(ZoneOffset.UTC),p.settledAt());assertEquals(id(22),p.receiptArtifact().artifactId());verify(resources,times(2)).require(eq(admission),any(),eq("artifact.read"),eq("MODEL_VERIFICATION"));verify(authorized).requireCurrent();}
 @Test void changedCurrentAuthorityCannotMintProof()throws Exception{when(current.require(admission,job,false)).thenThrow(new TenantAccessException(ErrorCode.ACCESS_DENIED));assertThrows(TenantAccessException.class,this::proof);verifyNoInteractions(settlement,objects);}
 @Test void selfConsistentNormalizedUsageCannotOverrideActualRawBytes(){((ObjectNode)result.required("usage")).put("total_tokens",6);assertThrows(TenantAccessException.class,this::proof);}
 @Test void changedAmountCannotBeAcceptedAgainstActualPriceAndUsage(){receipt.put("known_amount","0.00000400");assertThrows(TenantAccessException.class,this::proof);}
 @Test void wrongUsageReceiptCannotMintProof(){receipt.put("usage_receipt_id",id(99));assertThrows(TenantAccessException.class,this::proof);}
 @Test void differentFixedModelInSameScopeFails(){result.put("model_config_revision",id(99));assertThrows(TenantAccessException.class,this::proof);}
 @Test void rewrittenDispatchManifestWithoutIndependentWitnessFails()throws Exception{((ObjectNode)binding.required("actual_send_manifest")).put("request_sha256","b".repeat(64));binding.put("request_sha256","b".repeat(64)).put("actual_send_sha256",schema.hash(binding.required("actual_send_manifest")));assertThrows(TenantAccessException.class,this::proof);}
 @Test void unknownSettlementCannotMintConnectionSuccess(){when(record.settled()).thenReturn(false);assertThrows(TenantAccessException.class,this::proof);verifyNoInteractions(objects);}
 public static void main(String[] args)throws Throwable{int count=0;for(var m:ConnectionCompletedProofTest.class.getDeclaredMethods())if(m.isAnnotationPresent(Test.class)){try{m.invoke(new ConnectionCompletedProofTest());}catch(java.lang.reflect.InvocationTargetException e){throw e.getCause();}count++;}System.out.println("PASS "+count+" real completed proof integration tests");}
}
